import { rng } from '../types';

/* ---------- 1. SLIDING TILES — always solvable (generated by walking back from solved) ---------- */
export interface SlideP { kind: 'slide'; n: number; tiles: number[]; blank: number; par: number }
export function makeSlide(n: number, seed: number): SlideP {
  const tiles = Array.from({ length: n * n }, (_, i) => (i + 1) % (n * n));
  let blank = n * n - 1;
  const r = rng(seed);
  const steps = n * n * 14;
  let last = -1;
  for (let k = 0; k < steps; k++) {
    const moves = slideNeighbours(blank, n).filter((m) => m !== last);
    const pick = moves[Math.floor(r() * moves.length)];
    tiles[blank] = tiles[pick]; tiles[pick] = 0; last = blank; blank = pick;
  }
  return { kind: 'slide', n, tiles, blank, par: Math.round(steps / 8) };
}
export function slideNeighbours(i: number, n: number) {
  const r = Math.floor(i / n), c = i % n; const out: number[] = [];
  if (r > 0) out.push(i - n); if (r < n - 1) out.push(i + n);
  if (c > 0) out.push(i - 1); if (c < n - 1) out.push(i + 1);
  return out;
}
export const slideSolved = (p: SlideP) => p.tiles.every((t, i) => t === (i + 1) % (p.n * p.n));

/* ---------- 2. CIRCUIT GRID (lights-out) — generated from solved, so always solvable ---------- */
export interface LightsP { kind: 'lights'; n: number; cells: boolean[]; solution: number[] }
export function makeLights(n: number, seed: number, presses = 6): LightsP {
  const cells = new Array(n * n).fill(false);
  const r = rng(seed);
  const solution: number[] = [];
  const used = new Set<number>();
  while (solution.length < presses) {
    const i = Math.floor(r() * n * n);
    if (used.has(i)) continue;
    used.add(i); solution.push(i);
    for (const t of lightsToggle(i, n)) cells[t] = !cells[t];
  }
  return { kind: 'lights', n, cells, solution };
}
export function lightsToggle(i: number, n: number) {
  const r = Math.floor(i / n), c = i % n; const out = [i];
  if (r > 0) out.push(i - n); if (r < n - 1) out.push(i + n);
  if (c > 0) out.push(i - 1); if (c < n - 1) out.push(i + 1);
  return out;
}
export const lightsSolved = (p: LightsP) => p.cells.every((c) => !c);

/* ---------- 3. NUMBER LOCK — deduction, deterministic feedback ---------- */
export interface LockP { kind: 'lock'; len: number; digits: number; code: number[]; tries: number }
export function makeLock(len: number, digits: number, seed: number): LockP {
  const r = rng(seed);
  return { kind: 'lock', len, digits, code: Array.from({ length: len }, () => Math.floor(r() * digits) + 1), tries: 8 };
}
export function lockFeedback(code: number[], guess: number[]) {
  let exact = 0, partial = 0;
  const cRest: number[] = [], gRest: number[] = [];
  for (let i = 0; i < code.length; i++) {
    if (code[i] === guess[i]) exact++;
    else { cRest.push(code[i]); gRest.push(guess[i]); }
  }
  const pool = [...cRest];
  for (const g of gRest) { const k = pool.indexOf(g); if (k >= 0) { partial++; pool.splice(k, 1); } }
  return { exact, partial };
}

/* ---------- 4. PATTERN ECHO — deterministic sequence from seed ---------- */
export interface EchoP { kind: 'echo'; pads: number; sequence: number[] }
export function makeEcho(pads: number, length: number, seed: number): EchoP {
  const r = rng(seed);
  return { kind: 'echo', pads, sequence: Array.from({ length }, () => Math.floor(r() * pads)) };
}

/* ---------- 5. VOLT SUM (kakurasu) — built from a known solution ---------- */
export interface SumP { kind: 'sum'; n: number; rowTargets: number[]; colTargets: number[]; solution: boolean[] }
export function makeSum(n: number, seed: number): SumP {
  const r = rng(seed);
  const solution = Array.from({ length: n * n }, () => r() < 0.42);
  const rowTargets = new Array(n).fill(0), colTargets = new Array(n).fill(0);
  for (let i = 0; i < n * n; i++) {
    if (!solution[i]) continue;
    const row = Math.floor(i / n), col = i % n;
    rowTargets[row] += col + 1;
    colTargets[col] += row + 1;
  }
  return { kind: 'sum', n, rowTargets, colTargets, solution };
}
export function sumSolved(p: SumP, picked: boolean[]) {
  const n = p.n;
  for (let row = 0; row < n; row++) {
    let t = 0; for (let col = 0; col < n; col++) if (picked[row * n + col]) t += col + 1;
    if (t !== p.rowTargets[row]) return false;
  }
  for (let col = 0; col < n; col++) {
    let t = 0; for (let row = 0; row < n; row++) if (picked[row * n + col]) t += row + 1;
    if (t !== p.colTargets[col]) return false;
  }
  return true;
}

export type AnyPuzzle = SlideP | LightsP | LockP | EchoP | SumP;
export const PUZZLE_KINDS = ['slide', 'lights', 'lock', 'echo', 'sum'] as const;
export type PuzzleKind = (typeof PUZZLE_KINDS)[number];

export const PUZZLE_INFO: Record<PuzzleKind, { name: string; blurb: string; rule: string }> = {
  slide:  { name: 'Shard Slide',  blurb: 'Sliding tiles', rule: 'Slide the shards until the numbers run in order with the gap last.' },
  lights: { name: 'Circuit Grid', blurb: 'Lights out',     rule: 'Tapping a node flips it and its neighbours. Shut every node down.' },
  lock:   { name: 'Volt Lock',    blurb: 'Deduction',      rule: 'Crack the code. Gold = right digit, right slot. Blue = right digit, wrong slot.' },
  echo:   { name: 'Pattern Echo', blurb: 'Memory',         rule: 'Watch the surge, then repeat it. The sequence grows each round.' },
  sum:    { name: 'Volt Sum',     blurb: 'Number logic',   rule: 'Charge cells so each row and column matches its target. Column k is worth k.' },
};
